CREATE TABLE IF NOT EXISTS "study_material_t" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "study_material_t_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"title" varchar(255) NOT NULL,
	"material_type" varchar(30) DEFAULT 'NOTES',
	"subject_id" integer,
	"department_id" integer,
	"semester" varchar(20),
	"scheme" varchar(40),
	"academic_year" varchar(20),
	"exam_session" varchar(40),
	"module_no" varchar(20),
	"description" text,
	"uploaded_by" integer,
	"created_by" integer,
	"updated_by" integer,
	"created_at" timestamp DEFAULT now(),
	"updated_at" timestamp DEFAULT now(),
	"display" varchar(1) DEFAULT 'Y'
);
